import pandas as pd

def clean(df):
    d = df.copy()
    for c in ['Category', 'Region', 'Product']:
        if c in d.columns:
            d[c] = d[c].astype('string').str.strip()
    d['Region'] = d['Region'].str.title()
    d['Region'] = d['Region'].replace({'Suoth': 'South', 'Nort': 'North'})
    d['Date'] = pd.to_datetime(d['Date'], errors='coerce')
    for c in ['Quantity', 'Price', 'Revenue']:
        if c in d.columns:
            d[c] = pd.to_numeric(d[c], errors='coerce')
    d['Revenue'] = d['Quantity'] * d['Price']
    return d

def answer(df):
    d = clean(df)
    d = d[d['Category'].fillna('').eq('Electronics')]
    d = d[d['Region'].isin(['North', 'South', 'East', 'West'])]
    d = d.dropna(subset=['Region'])
    out = d.groupby('Region', dropna=True)['Revenue'].sum().sort_index()
    return {str(k): float(v) for k, v in out.items()}
